const input = $json || {};

function firstValue(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return String(value).trim();
    }
  }
  return '';
}

function compactRaw(value) {
  if (!value || typeof value !== 'object') return {};
  return {
    source: value.source || null,
    channel: value.channel || value.normalized_event?.channel || null,
    provider: value.provider || value.routing?.provider || null,
    external_channel_id: value.external_channel_id || value.phone_number_id || value.routing?.external_channel_id || value.routing?.phone_number_id || value.normalized_event?.external_channel_id || value.normalized_event?.phone_number_id || null,
    message_id: value.message_id || value.normalized_event?.message_id || value.event?.message_id || null,
    lead_id: value.lead_id || value.normalized_event?.lead_id || value.event?.lead_id || null
  };
}

const normalizedEvent = input.normalized_event || {};
const routing = input.routing || {};
const event = input.event || {};
const sourceMetadata = input.source_metadata || event.source_metadata || normalizedEvent.source_metadata || {};
const metaPayload = input.body || input;
const metadata = metaPayload?.entry?.[0]?.changes?.[0]?.value?.metadata || {};

const externalChannelId = firstValue(
  input.external_channel_id,
  routing.external_channel_id,
  normalizedEvent.external_channel_id,
  sourceMetadata.external_channel_id,
  input.phone_number_id,
  routing.phone_number_id,
  normalizedEvent.phone_number_id,
  sourceMetadata.phone_number_id,
  metadata.phone_number_id
);

const phoneNumberId = firstValue(
  input.phone_number_id,
  routing.phone_number_id,
  normalizedEvent.phone_number_id,
  sourceMetadata.phone_number_id,
  metadata.phone_number_id,
  externalChannelId
);

const displayPhoneNumber = firstValue(
  input.display_phone_number,
  routing.display_phone_number,
  normalizedEvent.display_phone_number,
  sourceMetadata.display_phone_number,
  metadata.display_phone_number
);

const channel = firstValue(input.channel, normalizedEvent.channel, event.channel, 'whatsapp');
const provider = firstValue(input.provider, routing.provider, sourceMetadata.provider, 'meta_whatsapp_cloud_api');
const leadId = firstValue(input.lead_id, normalizedEvent.lead_id, event.lead_id, normalizedEvent.from, event.from);
const messageId = firstValue(input.message_id, normalizedEvent.message_id, event.message_id);

return [{
  json: {
    ...input,
    resolver_input: {
      channel,
      provider,
      external_channel_id: externalChannelId || null,
      phone_number_id: phoneNumberId || null,
      display_phone_number: displayPhoneNumber || null,
      lead_id: leadId || null,
      message_id: messageId || null,
      raw: compactRaw(input)
    }
  }
}];

const row = $json || {};

function asObject(value, fallback = {}) {
  if (value === null || value === undefined) return fallback;
  if (typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : fallback;
    } catch {
      return fallback;
    }
  }
  return fallback;
}

function asBool(value) {
  if (value === true) return true;
  if (value === false) return false;
  const text = String(value || '').toLowerCase();
  if (text === 'true') return true;
  if (text === 'false') return false;
  return false;
}

function safePart(value, fallback) {
  const text = String(value || fallback || '').trim();
  return text.replace(/[^a-zA-Z0-9_.:-]/g, '_') || fallback;
}

const input = asObject(row.input, {});
const organization = asObject(row.organization, {});
const agent = asObject(row.agent, {});
const channelConfig = asObject(row.channel_config, {});
const routing = asObject(row.routing, {});
const shouldProcess = asBool(row.should_process);
const notProcessedReason = shouldProcess ? null : (row.not_processed_reason || row.error_code || 'channel_not_processable');
const channel = routing.channel || input.channel || 'whatsapp';
const provider = routing.provider || input.provider || 'meta_whatsapp_cloud_api';
const externalChannelId = routing.external_channel_id || input.external_channel_id || input.phone_number_id || null;
const leadId = input.lead_id || null;
const messageId = input.message_id || null;
const idempotencyKey = [
  'channel_config',
  safePart(provider, 'provider'),
  safePart(externalChannelId, 'missing_external_channel_id'),
  safePart(messageId || leadId, 'no_message')
].join('__');

return [{
  json: {
    should_process: shouldProcess,
    not_processed_reason: notProcessedReason,
    organization,
    agent,
    channel_config: channelConfig,
    routing: {
      channel,
      provider,
      external_channel_id: externalChannelId,
      phone_number_id: routing.phone_number_id || input.phone_number_id || null,
      organization_id: routing.organization_id || organization.id || null,
      agent_id: routing.agent_id || agent.id || null,
      environment: routing.environment || channelConfig.config?.environment || 'production',
      resolution_source: routing.resolution_source || channelConfig.resolution_source || null
    },
    input,
    error_code: shouldProcess ? null : (row.error_code || notProcessedReason),
    error_message: shouldProcess ? null : (row.error_message || notProcessedReason),
    audit: {
      event_type: shouldProcess ? 'channel_config_resolved' : 'channel_config_discarded',
      reason_code: notProcessedReason,
      idempotency_key: idempotencyKey,
      normalized_ok: shouldProcess,
      channel,
      provider,
      external_channel_id: externalChannelId,
      lead_id: leadId,
      message_id: messageId,
      organization_id: routing.organization_id || organization.id || null,
      agent_id: routing.agent_id || agent.id || null,
      resolved_at: new Date().toISOString()
    }
  }
}];

const resolverItems = $items('build_resolver_output', 0, 0);
const output = resolverItems?.[0]?.json || $json || {};
return [{ json: output }];

